137	function parsePathSegments(path, label) {
138	  if (typeof path !== 'string' || path.length === 0) {
139	    throw new Error(`${label}: path must be a non-empty string`);
140	  }
141	  const segments = path.split('.');
142	  if (segments.some(part => part.length === 0)) {
143	    throw new Error(`${label}: path must not contain empty segments`);
144	  }
145	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
146	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
147	  }
148	  return segments;
149	}
150	
151	function isComparableConstant(value) {
152	  return value === null || typeof value === 'string' || typeof value === 'boolean'
153	    || (typeof value === 'number' && Number.isFinite(value));
154	}
155	
156	function toComparableNumber(value) {
157	  // Objects and arrays never participate in numeric comparison, even though
158	  // Number([]) === 0; everything else uses JS numeric conversion.
159	  if (value !== null && typeof value === 'object') return null;
160	  const converted = Number(value);
161	  return Number.isFinite(converted) ? converted : null;
162	}
163	
164	// Validates an output reference of the shape
165	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
166	// reference itself must be a non-array object, nodeId must name an action
167	// node in this definition (matched as a whole string — dots are literal),
168	// and path, when present, follows the same segment rules as input paths.
169	function compileOutputReference(ref, nodes, label) {
170	  if (!isUsableObject(ref)) {
171	    throw new Error(`${label}: output reference must be a non-array object`);
172	  }
173	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
174	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
175	  }
176	  const target = nodes.get(ref.nodeId);
177	  if (!target) {
178	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
179	  }
180	  if (target.type !== 'action') {
181	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
182	  }
183	  let segments = [];
184	  if (Object.hasOwn(ref, 'path')) {
185	    segments = parsePathSegments(ref.path, `${label} path`);
186	  }
187	  return { nodeId: ref.nodeId, segments };
188	}
189	
190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    const childList = condition[key];
221	    if (!Array.isArray(childList)) {
222	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
223	    }
224	    if (childList.length === 0) {
225	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
226	    }
227	    // A non-empty array may still carry length without a condition at every
228	    // slot: a child deleted through the JavaScript API can leave a hole, or
229	    // the array may have been allocated with gaps only. A missing slot is a
230	    // definition error at its own original index — it is never treated as
231	    // false, skipped over or filled in — so it is reported even when an
232	    // earlier sibling would already short-circuit the compound. Explicit
233	    // undefined/null entries are not holes: they remain present and fall
234	    // through to the ordinary "condition must be an object" rejection.
235	    const children = [];
236	    for (let index = 0; index < childList.length; index += 1) {
237	      if (!Object.hasOwn(childList, index)) {
238	        throw new Error(`condition node ${nodeId} at ${position}.${key}[${index}]: ${key}[${index}] is a missing child condition`);
239	      }
240	      children.push(
241	        compileCondition(childList[index], nodes, nodeId, `${position}.${key}[${index}]`, depth + 1));
242	    }
243	    return { kind: key, children };
244	  }
245	
246	  const where = `condition node ${nodeId} at ${position}`;
247	  const hasField = Object.hasOwn(condition, 'field');
248	  const hasOutputField = Object.hasOwn(condition, 'outputField');
249	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
250	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
251	  }
252	  if (hasField && hasOutputField) {
253	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
254	  }
255	
256	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
257	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
258	  }
259	
260	  let left;
261	  if (hasField) {
262	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
263	  } else {
264	    left = {
265	      kind: 'output', label: 'outputField',
266	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
267	    };
268	  }
269	
270	  if (condition.operator === 'exists') {
271	    const unexpected = presentComparisonKeys.filter(key =>
272	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
273	    if (unexpected.length > 0) {
274	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
275	    }
276	    return { kind: 'comparison', operator: 'exists', left };
277	  }
278	
279	  const hasValue = Object.hasOwn(condition, 'value');
280	  const hasValueField = Object.hasOwn(condition, 'valueField');
281	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
282	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
283	  if (rightCount !== 1) {
284	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
285	  }
286	
287	  let right;
288	  if (hasValue) {
289	    if (!isComparableConstant(condition.value)) {
290	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
291	    }
292	    right = { kind: 'constant', label: 'value', value: condition.value };
293	    if (condition.operator !== 'eq') {
294	      const numericValue = toComparableNumber(condition.value);
295	      if (numericValue === null) {
296	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
297	      }
298	      right.numericValue = numericValue;
299	    }
300	  } else if (hasValueField) {
301	    if (typeof condition.valueField !== 'string') {
302	      throw new Error(`${where} valueField: path must be a non-empty string`);
303	    }
304	    right = {
305	      kind: 'input', label: 'valueField',
306	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
307	    };
308	  } else {
309	    right = {
310	      kind: 'output', label: 'valueOutputField',
311	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
312	    };
313	  }
314	
315	  return { kind: 'comparison', operator: condition.operator, left, right };
316	}
317	
318	const successorTargets = new WeakMap();
319	const nodeDependencies = new WeakMap();
320	
321	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
322	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
323	
324	function isIntegerIn(value, min, max) {
325	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
326	}
327	
328	// A retry block is either absent (one attempt, no waiting) or present with all
329	// four parameters together, each within the same ranges the engine enforces
330	// for business action retries and compensation retries alike.
331	function compileRetry(config, label) {
332	  if (!isUsableObject(config)) {
333	    throw new Error(`${label}: retry must be an object`);
334	  }
335	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
336	  if (missing.length > 0) {
337	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
338	  }
339	  if (!isIntegerIn(config.attempts, 1, 10)) {
340	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
341	  }
342	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
343	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
344	  }
345	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
346	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
347	  }
348	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
349	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
350	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
351	  }
352	  if (config.maxDelayMs < config.initialDelayMs) {
353	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
354	  }
355	  return {
356	    attempts: config.attempts,
357	    initialDelayMs: config.initialDelayMs,
358	    backoffFactor: config.backoffFactor,
359	    maxDelayMs: config.maxDelayMs,
360	  };
361	}
362	
363	// An action node either keeps the legacy `message` behavior, names a business
364	// operation the caller supplies at run time, and/or declares a compensation
365	// operation that undoes its business effect. Both retry blocks are optional
366	// and, absent, mean exactly one attempt with no waiting.
367	function compileAction(node) {
368	  let name = null;
369	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
370	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
371	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
372	    }
373	    name = node.operation;
374	  }
375	
376	  let retry = { ...DEFAULT_RETRY };
377	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
378	    if (!name) {
379	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
380	    }
381	    retry = compileRetry(node.retry, `action node ${node.id}`);
382	  }
383	
384	  let compensation = null;
385	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
386	    if (!isUsableObject(node.compensation)) {
387	      throw new Error(`action node ${node.id}: compensation must be an object`);
388	    }
389	    if (!name) {
390	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
391	    }
392	    const config = node.compensation;
393	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
394	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
395	    }
396	    let compRetry = { ...DEFAULT_RETRY };
397	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
398	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
399	    }
400	    compensation = { name: config.operation, retry: compRetry };
401	  }
402	
403	  // A legacy message action (no operation) is validated through the single
404	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
405	  // action-specific wording, that end-node results use — covering every
406	  // message action including ones on untaken branches and entry-unreachable
407	  // ones. An action that names an operation ignores its message entirely, so
408	  // an unused uncloneable or shared-memory message is never rejected for it.
409	  // The gate only proves the message was safe as it was then; the same rule
410	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
411	  if (name === null) {
412	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
413	  }
414	
415	  return { name, retry, compensation };
416	}
417	
418	// The two failure kinds a node-configured value can produce, shared by
419	// definition validation (assertConfiguredCopy below) and the execution-time
420	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
421	// all, or it clones but the clone retains shared memory. Uncloneability takes
422	// precedence when a value carries both, at both moments. Each node kind keeps
423	// its own wording — an action's message and an end node's result fail with the
424	// node-specific text the entries already exposed — and its own default for a
425	// value that is absent, undefined or null (action:<node id> for a legacy
426	// message; null for an end result), while "", 0 and false pass through
427	// untouched for both.
428	const ACTION_MESSAGE_COPY_ERRORS = {
429	  uncloneable: nodeId =>
430	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
431	  sharedMemory: nodeId =>
432	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
433	};
434	const END_RESULT_COPY_ERRORS = {
435	  uncloneable: nodeId =>
436	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
437	  sharedMemory: nodeId =>
438	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
439	};
440	
441	// The single independent-copy rule for a value a node configures — a legacy
442	// action's `message` and an end node's `result` both go through here, so the
443	// cloneability and retained-shared-memory rules are maintained in exactly one
444	// place and the two node kinds can never drift apart. It is invoked at two
445	// moments, and each moment keeps its original root-read protocol:
446	//
447	//  1. At validation time (assertConfiguredCopy), for every such node in the
448	//     definition — including nodes on untaken branches and nodes the entry
449	//     cannot reach — so a statically invalid value is rejected before any
450	//     node, business operation or compensation can run. An absent own
451	//     property is not read at all; the gate performs the first root read and
452	//     only an own, defined value reaches the clone, which performs the root's
453	//     second read itself (a throwing root accessor propagates from the gate
454	//     exactly as before).
455	//  2. At the node's own execution moment (readConfiguredCopy), against the
456	//     value actually about to be saved: the root is read exactly once and the
457	//     value that read produced is cloned, so validation cannot pin the result
458	//     — an enumerable getter's later answer and a preceding business
459	//     operation's or another activated branch's mutation are both captured.
460	//
461	// At either moment every nested enumerable accessor is read only by
462	// structuredClone's own read — there is no separate inspection pass over the
463	// original, so a getter's return order is never disturbed and the value the
464	// clone's read produced is both what is judged and what is saved (a legal
465	// value whose getter answers with a different ordinary value at execution
466	// time records that fresh value rather than the stale validation-time one). A
467	// root getter that throws on execution's single read, a nested getter that
468	// throws while the clone reads it, and a value that cannot be cloned at all
469	// (a bare function) all surface as the same uncloneable error.
470	//
471	// The copy itself is produced by independentCopy — the one clone-then-judge
472	// rule every saved value in this engine goes through (see its comment for why
473	// cloning must precede the shared-memory traversal and why uncloneability
474	// takes precedence). Only the wording of the failure is node-specific here.
475	//
476	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
477	// rather than recorded as a run status: the synchronous entry propagates it
478	// and the asynchronous entry's rejected Promise carries it. It is never an
479	// action_failed — neither node kind has a retry budget — it neither consumes
480	// business-action retries nor triggers compensation, and no output/result is
481	// recorded for the node. At execution, an absent, undefined or null value
482	// becomes `absentValue` (action:<node id> for messages, null for results),
483	// while "", 0 and false pass through untouched.
484	function configuredCopy(node, property, errors, options) {
485	  const validation = options !== undefined && options.validation === true;
486	
487	  if (validation) {
488	    // Preserve the validation gate exactly: no read at all for a missing own
489	    // property, one unguarded gate read (a throwing root accessor propagates
490	    // raw, as the former per-node gates did), and an undefined value is left
491	    // to execution. The structuredClone argument evaluation is the root's
492	    // second — and final — read this moment; the clone itself traverses that
493	    // captured value (firing nested getters once), so no read the original
494	    // gate made is added or removed.
495	    if (!Object.hasOwn(node, property)) return;
496	    const gated = node[property];
497	    if (gated === undefined) return;
498	    const copy = independentCopy(node[property]);
499	    if (!copy.ok) throw new Error(errors[copy.reason](node.id));
500	    return;
501	  }
502	
503	  // Execution: the root value's single read. An absent, undefined or null
504	  // value takes the node kind's default (action:<node id> for messages, null
505	  // for results) without reaching structuredClone; a root getter that throws
506	  // on this read is the uncloneable error.
507	  const { absentValue } = options;
